// Nearstudio component parameter bridge. The WebGL scene remains the original source runtime.
const nearstudioDorianDefaults={rotationSpeed:.6,fluidIOR:.13,fluidRoughness:.2,fluidSaturation:1.17,fluidContrast:.4,chromaticAberration:.15,bloom:.7,vignette:.25,warmColor:"#1f0d05",coolColor:"#0f001f"};
let nearstudioDorianParameters={...nearstudioDorianDefaults};
const nearstudioDorianNumber=(key,min,max)=>{const value=Number(nearstudioDorianParameters[key]);return Number.isFinite(value)?Math.min(max,Math.max(min,value)):nearstudioDorianDefaults[key]};
const nearstudioDorianColor=(key)=>{const value=String(nearstudioDorianParameters[key]??"");return /^#[0-9a-fA-F]{6}$/.test(value)?value:nearstudioDorianDefaults[key]};
const nearstudioApplyDorianParameters=()=>{try{const scene=gi.getScene("main");if(!scene||scene.introState>.01)return;scene.glassRotSpeed=nearstudioDorianNumber("rotationSpeed",0,8);if(scene.fluidText){scene.fluidText.config.IOR.value=nearstudioDorianNumber("fluidIOR",0,2);scene.fluidText.config.RefractionRoughness.value=nearstudioDorianNumber("fluidRoughness",0,1);scene.fluidText.config.Saturation.value=nearstudioDorianNumber("fluidSaturation",0,2);scene.fluidText.config.Contrast.value=nearstudioDorianNumber("fluidContrast",-1,1);scene.fluidText.config.Color2.value=nearstudioDorianColor("warmColor");scene.fluidText.config.Color3.value=nearstudioDorianColor("coolColor");}if(scene.post){scene.post.config.ChromaticAberations.value=nearstudioDorianNumber("chromaticAberration",0,1);scene.post.config.BloomOpacity.value=nearstudioDorianNumber("bloom",0,1);scene.post.config.Vignette.value=nearstudioDorianNumber("vignette",0,1);}}catch(error){console.warn("Nearstudio Dorian parameter bridge",error);}};
window.addEventListener("message",event=>{if(event.origin!==window.location.origin||event.data?.type!=="nearstudio:dorian-config")return;nearstudioDorianParameters={...nearstudioDorianDefaults,...event.data.parameters};nearstudioApplyDorianParameters();});
